import pytest

def test_test_id_display(testdir):
    testdir.makepyfile("""
        import pytest

        @pytest.mark.parametrize("a",["..["])
        def test_boo(a):
            assert 0
    """)
    result = testdir.runpytest("-v")
    stdout = result.stdout.str()
    lines = stdout.splitlines()
    for line in lines:
        if line.startswith('_') and line.endswith('_') and 'test_boo[' in line:
            stripped = line.strip('_').strip()
            if stripped == "test_boo[..[]":
                return
            else:
                raise AssertionError(f"Expected test ID 'test_boo[..[]' but got '{stripped}'")
    raise AssertionError(f"Could not find test headline in output:\n{stdout}")

